}#stage .az-bar i.good{ background:linear-gradient(90deg, var(--accent-1), var(--success)); }#stage .az-sla-row b{ width:130px; flex-shrink:0; text-align:right; font-family:var(--font-mono); font-size:32px; font-weight:800; }#stage .az-sla-row b.bad{ color:var(--danger); }#stage .az-sla-row b.good{ color:var(--success); }#stage .az-hrs{ width:270px; flex-shrink:0; color:var(--text-dim); font-family:var(--font-mono); font-size:19px; }#stage .az-verdict{
  flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:16px 24px; border-radius:20px;
  background:rgba(20,27,43,.75); border:1.5px solid var(--border);
  transition:border-color .3s ease;
}#stage .az-verdict.win{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.08); }#stage .az-vl{
  padding:6px 14px; border-radius:8px; background:rgba(58,160,255,.14);
  border:1px solid rgba(58,160,255,.35); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.6px;
}#stage .az-verdict.win .az-vl{ background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.4); color:var(--success); }#stage .az-vt{ color:var(--text-primary); font-size:26px; font-weight:700; }#stage .az-strip{
  height:74px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 24px; border-radius:20px;
  background:rgba(20,27,43,.75); border:1.5px solid var(--border);
}#stage .az-strip-l{
  padding:7px 15px; border-radius:8px; background:rgba(58,160,255,.14);
  border:1px solid rgba(58,160,255,.35); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.8px;
  white-space:nowrap;
}#stage .az-strip.bad .az-strip-l{ background:rgba(244,74,106,.14); border-color:rgba(244,74,106,.4); color:var(--danger); }#stage .az-strip.good .az-strip-l{ background:rgba(63,185,80,.14); border-color:rgba(63,185,80,.4); color:var(--success); }#stage .az-strip-t{ color:var(--text-primary); font-size:25px; font-weight:600; }@keyframes az-drop{ from{ top:-24px; } to{ top:100%; } }

stages.js:
MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-one', 'on', true);
MSD.hide('.msd-reveal');
MSD.cls('#az-health', 'bad', false);
MSD.q('#az-health-t').textContent = 'healthy';
MSD.cls('.az-wire', 'broken', false);
MSD.cls('.az-tier-node', 'down', false);
MSD.cls('.az-tier-node', 'dark', false);
MSD.cls('#az-dc', 'down', false);
MSD.cls('#az-spof', 'on', false);
MSD.cls('#az-phone', 'bad', false);
MSD.cls('#az-phone', 'good', true);
MSD.cls('#az-msg', 'err', false);
MSD.cls('#az-msg', 'wait', false);
MSD.q('#az-msg').textContent = 'Signed in. Welcome back, Suthahar.';
MSD.q('#az-srv-s').textContent = 'running · 100% of traffic';
MSD.q('#az-srv-badge').textContent = 'UP';
MSD.q('#az-db-badge').textContent = 'UP';
MSD.cls('#az-strip', 'bad', false);
MSD.cls('#az-strip', 'good', false);
MSD.q('#az-strip-l').textContent = 'THE SETUP';
MSD.q('#az-strip-t').textContent = 'Millions of shoppers. One server holding all of them.';

MSD.count('#az-users-n', 4.18, 1500, { decimals: 2, suffix: ' M' });
MSD.after(120, function(){ MSD.show('.az-face', 90); });
MSD.after(800, function(){
  MSD.cls('#az-w1', 'flow', true);
  MSD.cls('#az-w2', 'flow', true);
  MSD.cls('#az-tier-s', 'live', true);
  MSD.sfx.pop();
});
MSD.after(900, function(){
  MSD.stream('#az-dc', { from: { x: 50, y: 22 }, to: { x: 50, y: 58 }, count: 5, duration: 850, gap: 700, spread: 90 });
});

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-one', 'on', true);
MSD.cls('#az-w1', 'flow', true);
MSD.cls('#az-w2', 'flow', true);
MSD.show('.az-face', 0, true);
MSD.q('#az-strip-l').textContent = 'THE RISK';
MSD.q('#az-strip-t').textContent = 'One machine, one room, one power feed — and no plan B.';

MSD.after(200, function(){ MSD.focus('#az-tier-s', '#az-tier-u, #az-tier-d, #az-phone'); });
MSD.after(1100, function(){ MSD.cls('#az-spof', 'on', true); MSD.sfx.error(); });
MSD.after(1500, function(){ MSD.punch('#az-spof', 2); });
MSD.after(1900, function(){ MSD.unfocus(); MSD.flash('#az-dc'); });

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-one', 'on', true);
MSD.unfocus();
MSD.show('.az-face', 0, true);
MSD.cls('#az-spof', 'on', true);
MSD.cls('#az-strip', 'bad', true);
MSD.q('#az-strip-l').textContent = 'OUTAGE';
MSD.q('#az-strip-t').textContent = 'The server is down — and it was the only one.';

MSD.q('#az-srv-s').textContent = 'maintenance · rebooting';
MSD.after(500, function(){ MSD.shake('#az-tier-s'); });
MSD.after(900, function(){
  MSD.cls('#az-w1', 'flow', false);
  MSD.cls('#az-w2', 'flow', false);
  MSD.cls('#az-w1', 'broken', true);
  MSD.cls('#az-tier-s', 'live', false);
  MSD.cls('#az-tier-s', 'down', true);
  MSD.q('#az-srv-s').textContent = 'offline · not responding';
  MSD.q('#az-srv-badge').textContent = 'DOWN';
  MSD.sfx.error();
});
MSD.after(1400, function(){
  MSD.cls('#az-w2', 'broken', true);
  MSD.cls('#az-tier-d', 'dark', true);
  MSD.q('#az-db-badge').textContent = 'CUT OFF';
  MSD.q('#az-db-s').textContent = 'nothing can reach it';
  MSD.sfx.thud();
});
MSD.after(1800, function(){
  MSD.cls('#az-dc', 'down', true);
  MSD.cls('#az-health', 'bad', true);
  MSD.q('#az-health-t').textContent = 'outage';
  MSD.flash('#az-health');
});

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-one', 'on', true);
MSD.show('.az-face', 0, true);
MSD.cls('#az-spof', 'on', true);
MSD.cls('#az-strip', 'bad', true);
MSD.q('#az-strip-l').textContent = 'THE CUSTOMER';
MSD.q('#az-strip-t').textContent = 'They never see your server. They see a broken shop.';

MSD.after(150, function(){ MSD.focus('#az-phone', '#az-dc'); });
MSD.after(500, function(){ MSD.cls('#az-btn', 'press', true); MSD.sfx.tick(); });
MSD.after(720, function(){
  MSD.cls('#az-btn', 'press', false);
  MSD.cls('#az-btn', 'wait', true);
  MSD.q('#az-btn').textContent = 'Signing in…';
  MSD.cls('#az-phone', 'good', false);
  MSD.cls('#az-msg', 'wait', true);
  MSD.q('#az-msg').textContent = 'Connecting to the server…';
});
MSD.after(1700, function(){
  MSD.cls('#az-msg', 'wait', false);
  MSD.cls('#az-msg', 'err', true);
  MSD.cls('#az-phone', 'bad', true);
  MSD.q('#az-msg').textContent = 'We could not sign you in. Try again later.';
  MSD.q('#az-btn').textContent = 'Try again';
  MSD.shake('#az-phone');
});
MSD.after(2150, function(){
  MSD.cls('#az-cartline', 'bad', true);
  MSD.q('#az-cart-v').textContent = 'cart lost';
  MSD.sfx.error();
});

MSD.unfocus();
MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-cost', 'on', true);
MSD.hide('.az-cost');
MSD.cls('.az-cost', 'hot', false);
MSD.cls('#az-rating', 'drop', false);
MSD.q('#az-users-n').textContent = '0';
MSD.cls('#az-strip', 'bad', true);
MSD.q('#az-strip-l').textContent = 'IMPACT';
MSD.q('#az-strip-t').textContent = 'Downtime is not a technical event. It is a business event.';

MSD.count('#az-down', 47, 2200, { suffix: ' min' });
MSD.count('#az-rev', 1.9, 2200, { prefix: '$', decimals: 1, suffix: ' M' });
MSD.after(200, function(){ MSD.show('.az-cost', 260); });
MSD.after(1500, function(){ MSD.cls('.az-cost', 'hot', true); MSD.sfx.error(); });
MSD.after(2000, function(){ MSD.cls('#az-rating', 'drop', true); MSD.punch('#az-rating', 3); });

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-zone', 'on', true);
MSD.cls('#az-sc-zone', 'sla', false);
MSD.cls('#az-sc-zone', 'write', false);
MSD.cls('#az-sc-zone', 'deployed', false);
MSD.hide('.az-fac, .az-app, .az-rep, .az-gauge, #az-lb');
['#az-gb1','#az-gb2','#az-gb3'].forEach(function(sel){ MSD.q(sel).style.width = '0%'; });
MSD.cls('.az-zone', 'live', false);
MSD.cls('.az-zone', 'dead', false);
MSD.cls('#az-verdict', 'win', false);
MSD.cls('#az-health', 'bad', false);
MSD.q('#az-health-t').textContent = 'on Azure';
MSD.q('#az-users-n').textContent = '4.18 M';
MSD.cls('#az-strip', 'bad', false);
MSD.q('#az-strip-l').textContent = 'THE FIX';
MSD.q('#az-strip-t').textContent = 'Three buildings, kilometres apart, inside one region.';
MSD.q('#az-vt').textContent = 'One region. Three independent failure domains.';
['#az-s1','#az-s2','#az-s3'].forEach(function(sel){ MSD.q(sel).textContent = 'ready'; });

MSD.after(250, function(){ MSD.punch('#az-region', 1); MSD.sfx.pop(); });
MSD.after(500, function(){ MSD.show('#az-z1 .az-fac, #az-z2 .az-fac, #az-z3 .az-fac', 110); });
MSD.after(1800, function(){ MSD.flash('#az-lat'); MSD.sfx.lock(); });
MSD.after(2100, function(){ MSD.punch('#az-verdict', 3); });

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-zone', 'on', true);
MSD.cls('#az-sc-zone', 'sla', false);
MSD.cls('#az-sc-zone', 'write', false);
MSD.cls('#az-sc-zone', 'deployed', true);
MSD.show('.az-fac', 0, true);
MSD.hide('.az-app, .az-rep, .az-gauge');
MSD.cls('.az-rep', 'writing', false);
MSD.cls('.az-rep', 'acked', false);
MSD.qa('.az-rep').forEach(function(el){ el.textContent = 'DB replica · in sync'; });
['#az-gb1','#az-gb2','#az-gb3'].forEach(function(sel){ MSD.q(sel).style.width = '0%'; });
MSD.q('#az-strip-l').textContent = 'DEPLOY';
MSD.q('#az-strip-t').textContent = 'Same app, three copies — the load balancer splits the traffic.';
MSD.q('#az-vt').textContent = 'No single machine, room or power feed can take the shop down.';

MSD.after(100, function(){ MSD.show('#az-lb', 0); });
MSD.after(400, function(){ MSD.show('#az-a1, #az-a2, #az-a3', 200); });
MSD.after(1000, function(){ MSD.show('#az-r1, #az-r2, #az-r3', 180); });
MSD.after(1400, function(){ MSD.show('#az-g1, #az-g2, #az-g3', 120, true); });
['#az-z1','#az-z2','#az-z3'].forEach(function(sel, i){
  MSD.after(1500 + i * 200, function(){ MSD.cls(sel, 'live', true); MSD.sfx.step(i); });
});
MSD.after(1600, function(){
  ['#az-s1','#az-s2','#az-s3'].forEach(function(sel){ MSD.q(sel).textContent = 'serving 33%'; });
  ['#az-gb1','#az-gb2','#az-gb3'].forEach(function(sel){ MSD.q(sel).style.width = '33%'; });
  MSD.stream('#az-region', { from: { x: 50, y: 2 }, to: { x: 16, y: 62 }, count: 4, duration: 900, gap: 800, spread: 20 });
  MSD.stream('#az-region', { from: { x: 50, y: 2 }, to: { x: 50, y: 62 }, count: 4, duration: 900, gap: 800, spread: 20 });
  MSD.stream('#az-region', { from: { x: 50, y: 2 }, to: { x: 84, y: 62 }, count: 4, duration: 900, gap: 800, spread: 20 });
});
MSD.after(2400, function(){ MSD.punch('#az-verdict', 4); });

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-zone', 'on', true);
MSD.cls('#az-sc-zone', 'sla', false);
MSD.cls('#az-sc-zone', 'deployed', true);
MSD.cls('#az-sc-zone', 'write', true);
MSD.show('.az-app, .az-rep, .az-gauge, #az-lb', 0, true);
MSD.cls('.az-zone', 'live', true);
MSD.cls('.az-rep', 'writing', false);
MSD.cls('.az-rep', 'acked', false);
MSD.cls('.az-wstep', 'on', false);
MSD.cls('.az-wstep', 'done', false);
MSD.q('#az-write-ms').textContent = '+0 ms';
MSD.q('#az-strip-l').textContent = 'REPLICATION';
MSD.q('#az-strip-t').textContent = 'Close enough to copy every write before answering the customer.';
MSD.q('#az-vl').textContent = 'RESULT';
MSD.q('#az-vt').textContent = 'A zone can die mid-write. The other two already have the data.';

// Beat 1 — the write arrives in zone 1 and is not yet safe anywhere.
MSD.after(150, function(){
  MSD.cls('#az-ws1', 'on', true);
  MSD.q('#az-r1').textContent = 'writing…';
  MSD.cls('#az-r1', 'writing', true);
  MSD.sfx.blip(0);
});
// Beat 2 — it fans out across the region on the sub-2 ms links.
MSD.after(900, function(){
  MSD.cls('#az-ws2', 'on', true);
  MSD.q('#az-r2').textContent = 'writing…';
  MSD.q('#az-r3').textContent = 'writing…';
  MSD.cls('#az-r2', 'writing', true);
  MSD.cls('#az-r3', 'writing', true);
  MSD.q('#az-write-ms').textContent = '+0.8 ms';
  MSD.particles('#az-region', { from: { x: 18, y: 32 }, to: { x: 50, y: 32 }, count: 5, duration: 520, spread: 10 });
  MSD.particles('#az-region', { from: { x: 18, y: 32 }, to: { x: 84, y: 32 }, count: 5, duration: 620, spread: 10 });
  MSD.sfx.data(1);
});
// Beat 3 — every replica confirms. This is the step people skip.
MSD.after(1750, function(){
  MSD.cls('#az-ws3', 'on', true);
  ['#az-r1', '#az-r2', '#az-r3'].forEach(function(sel, i){
    MSD.after(i * 120, function(){
      MSD.q(sel).textContent = '✓ committed';
      MSD.cls(sel, 'writing', false);
      MSD.cls(sel, 'acked', true);
      MSD.sfx.step(i);
    });
  });
  MSD.q('#az-write-ms').textContent = '+1.6 ms';
});
// Beat 4 — only now does the customer hear "added to cart".
MSD.after(2450, function(){
  MSD.cls('#az-ws4', 'on', true);
  MSD.cls('.az-wstep', 'done', true);
  MSD.q('#az-write-t').textContent = 'Committed in three buildings before the customer sees it';
  MSD.flash('#az-verdict');
  MSD.sfx.lock();
});

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-zone', 'on', true);
MSD.cls('#az-sc-zone', 'sla', false);
MSD.cls('#az-sc-zone', 'write', false);
MSD.cls('#az-sc-zone', 'deployed', true);
MSD.show('.az-fac, .az-app, .az-rep, .az-gauge, #az-lb', 0, true);
MSD.cls('.az-zone', 'live', true);
MSD.cls('.az-zone', 'dead', false);
MSD.cls('.az-rep', 'writing', false);
MSD.cls('.az-rep', 'acked', false);
MSD.qa('.az-rep').forEach(function(el){ el.textContent = 'DB replica · in sync'; });
['#az-gb1','#az-gb2','#az-gb3'].forEach(function(sel){ MSD.q(sel).style.width = '33%'; });
['#az-s1','#az-s2','#az-s3'].forEach(function(sel){ MSD.q(sel).textContent = 'serving 33%'; });
MSD.cls('#az-strip', 'bad', false);
MSD.q('#az-strip-l').textContent = 'FAILOVER';
MSD.q('#az-strip-t').textContent = 'An entire datacenter is gone. Checkout never stops.';

MSD.after(600, function(){
  MSD.shake('#az-z2');
  MSD.cls('#az-z2', 'live', false);
  MSD.cls('#az-z2', 'dead', true);
  MSD.q('#az-s2').textContent = 'zone down';
  MSD.q('#az-gb2').style.width = '0%';
  MSD.q('#az-lb-s').textContent = 'health probe failed · zone 2 removed';
  MSD.sfx.error();
});
MSD.after(1300, function(){
  MSD.q('#az-s1').textContent = 'serving 50%';
  MSD.q('#az-s3').textContent = 'serving 50%';
  MSD.q('#az-gb1').style.width = '50%';
  MSD.q('#az-gb3').style.width = '50%';
  // The payoff of the replication stage: the data was already here.
  ['#az-r1', '#az-r3'].forEach(function(sel){
    MSD.q(sel).textContent = 'has every write';
    MSD.cls(sel, 'acked', true);
  });
  MSD.q('#az-r2').textContent = 'DB replica · unreachable';
  MSD.punch('#az-z1', 1);
  MSD.punch('#az-z3', 2);
  MSD.stream('#az-region', { from: { x: 50, y: 2 }, to: { x: 16, y: 62 }, count: 5, duration: 800, gap: 700, spread: 20 });
  MSD.stream('#az-region', { from: { x: 50, y: 2 }, to: { x: 84, y: 62 }, count: 5, duration: 800, gap: 700, spread: 20 });
});
MSD.after(2000, function(){
  MSD.cls('#az-verdict', 'win', true);
  MSD.q('#az-vl').textContent = 'STILL UP';
  MSD.q('#az-vt').textContent = 'Customers keep logging in. Nobody notices anything.';
  MSD.q('#az-health-t').textContent = 'healthy';
  MSD.flash('#az-verdict');
  MSD.sfx.chime();
});

MSD.cls('.az-sc', 'on', false);
MSD.cls('#az-sc-zone', 'on', true);
MSD.cls('#az-sc-zone', 'sla', true);
MSD.cls('#az-sc-zone', 'write', false);
MSD.cls('#az-sc-zone', 'deployed', true);
MSD.show('.az-app, .az-rep, .az-gauge, #az-lb', 0, true);
MSD.cls('.az-rep', 'writing', false);
MSD.cls('.az-rep', 'acked', false);
MSD.qa('.az-rep').forEach(function(el){ el.textContent = 'DB replica · in sync'; });
MSD.cls('#az-z2', 'dead', false);
MSD.cls('.az-zone', 'live', true);
MSD.cls('#az-verdict', 'win', true);
MSD.cls('#az-strip', 'good', true);
MSD.q('#az-lb-s').textContent = 'all three zones healthy';
['#az-s1','#az-s2','#az-s3'].forEach(function(sel){ MSD.q(sel).textContent = 'serving 33%'; });
['#az-gb1','#az-gb2','#az-gb3'].forEach(function(sel){ MSD.q(sel).style.width = '33%'; });
MSD.q('#az-vl').textContent = 'THE DEAL';
MSD.q('#az-vt').textContent = 'Same code. Same region. One checkbox at deploy time.';
MSD.q('#az-strip-l').textContent = 'THE PAYOFF';
MSD.q('#az-strip-t').textContent = 'Availability is an architecture decision, not a support ticket.';
MSD.q('#az-b1').style.width = '0%';
MSD.q('#az-b2').style.width = '0%';
MSD.q('#az-b2').classList.add('good');

MSD.after(300, function(){ MSD.q('#az-b1').style.width = '56%'; MSD.sfx.step(0); });
MSD.after(1000, function(){ MSD.q('#az-b2').style.width = '100%'; MSD.sfx.sparkle(); });
MSD.after(1900, function(){ MSD.punch('#az-verdict', 4); MSD.flash('#az-region'); });
